import AVFoundation
import AppKit

let args = CommandLine.arguments
guard args.count >= 4 else {
    print("usage: extract_frames <video> <outdir> <count>")
    exit(1)
}
let url = URL(fileURLWithPath: args[1])
let outDir = args[2]
let count = Int(args[3]) ?? 12

let asset = AVAsset(url: url)
let duration = CMTimeGetSeconds(asset.duration)
print("duration: \(duration)s")

let gen = AVAssetImageGenerator(asset: asset)
gen.appliesPreferredTrackTransform = true
gen.requestedTimeToleranceBefore = .zero
gen.requestedTimeToleranceAfter = CMTime(seconds: 0.5, preferredTimescale: 600)
gen.maximumSize = CGSize(width: 1280, height: 1280)

for i in 0..<count {
    let t = duration * (Double(i) + 0.5) / Double(count)
    let time = CMTime(seconds: t, preferredTimescale: 600)
    do {
        let cg = try gen.copyCGImage(at: time, actualTime: nil)
        let rep = NSBitmapImageRep(cgImage: cg)
        guard let data = rep.representation(using: .jpeg, properties: [.compressionFactor: 0.82]) else { continue }
        let name = String(format: "frame_%02d_t%03ds.jpg", i, Int(t))
        try data.write(to: URL(fileURLWithPath: "\(outDir)/\(name)"))
        print("wrote \(name)")
    } catch {
        print("frame \(i) failed: \(error.localizedDescription)")
    }
}

/* ============================================================================
   SAQEEL (صقيل) — DESIGN TOKENS (single source of raw values)
   Theme v2 · Saqeel dark — sponsor-directed retheme 2026-07-12 (launch film
   "Factory Health Platform — Launch Film v2" is the visual authority; the
   prior DGA ministry-green theme is retired by sponsor instruction).
   Rule: raw color/size values may appear ONLY in this file (MVP1-FND-010
   master-data governance applied to design tokens). All components consume
   var(--ax-*). Derived tints use color-mix() from approved base values —
   no new hex is invented outside the approved palette.
   ========================================================================== */

:root {
  /* ---- Color · Saqeel dark (qualified from launch film frames) ----
     Canvas = near-black indigo; surfaces = dark indigo cards with violet
     borders; primary = signal violet (map outlines, active nav); success =
     live emerald (healthy / live / synced); warning = amber (due / medium
     risk); critical = coral (high risk / overdue); info = sky. */
  --ax-color-primary:        #7C6CFF;  /* signal violet */
  --ax-color-primary-hover:  #9487FF;  /* lighter on dark theme */
  --ax-color-canvas:         #0A0A14;  /* near-black indigo */
  --ax-color-surface:        #14141F;  /* card indigo */
  --ax-color-text:           #EFEFF7;
  --ax-color-text-secondary: #9C9CB2;
  --ax-color-border:         #26263A;
  --ax-color-success:        #2DE08E;  /* live emerald */
  --ax-color-warning:        #E8B84B;
  --ax-color-critical:       #F0625D;  /* risk coral */
  --ax-color-info:           #5AA7FA;
  --ax-color-shadow-base:    #000000;  /* elevation base — never used directly */

  /* ---- Color · derived (color-mix from approved bases only) ----
     On the dark theme, tints mix toward the dark surface (tinted panels) and
     strong variants mix toward the light text (readable accents). */
  --ax-color-primary-tint:   color-mix(in srgb, var(--ax-color-primary) 14%, var(--ax-color-surface));
  --ax-color-primary-weak:   color-mix(in srgb, var(--ax-color-primary) 28%, var(--ax-color-surface));
  --ax-color-primary-strong: color-mix(in srgb, var(--ax-color-primary) 72%, var(--ax-color-text));
  --ax-color-success-tint:   color-mix(in srgb, var(--ax-color-success) 14%, var(--ax-color-surface));
  --ax-color-success-strong: color-mix(in srgb, var(--ax-color-success) 78%, var(--ax-color-text));
  --ax-color-warning-tint:   color-mix(in srgb, var(--ax-color-warning) 16%, var(--ax-color-surface));
  --ax-color-warning-strong: color-mix(in srgb, var(--ax-color-warning) 78%, var(--ax-color-text));
  --ax-color-critical-tint:  color-mix(in srgb, var(--ax-color-critical) 14%, var(--ax-color-surface));
  --ax-color-critical-strong:color-mix(in srgb, var(--ax-color-critical) 80%, var(--ax-color-text));
  --ax-color-info-tint:      color-mix(in srgb, var(--ax-color-info) 14%, var(--ax-color-surface));
  --ax-color-neutral-tint:   color-mix(in srgb, var(--ax-color-text-secondary) 10%, var(--ax-color-surface));
  --ax-color-neutral-weak:   color-mix(in srgb, var(--ax-color-text-secondary) 20%, var(--ax-color-surface));
  --ax-color-border-strong:  color-mix(in srgb, var(--ax-color-text-secondary) 45%, var(--ax-color-border));
  --ax-color-text-disabled:  color-mix(in srgb, var(--ax-color-text-secondary) 55%, var(--ax-color-surface));
  --ax-color-surface-sunken: color-mix(in srgb, var(--ax-color-canvas) 60%, var(--ax-color-surface));
  --ax-color-surface-raised: color-mix(in srgb, var(--ax-color-text) 5%, var(--ax-color-surface));
  --ax-color-overlay:        color-mix(in srgb, var(--ax-color-shadow-base) 60%, transparent);
  --ax-color-inverse-text:   var(--ax-color-canvas);   /* dark text on violet/emerald fills */

  /* ---- Typography (Saqeel v2) ----
     Space Grotesk carries EN display/UI (launch-film geometric sans);
     IBM Plex Sans Arabic carries AR; JetBrains Mono carries the uppercase
     data labels, IDs, coordinates and timers seen throughout the film. */
  --ax-font-sans: var(--font-grotesk, "Space Grotesk"), var(--font-plex-arabic, "IBM Plex Sans Arabic"), -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --ax-font-arabic: var(--font-plex-arabic, "IBM Plex Sans Arabic"), "Geeza Pro", "Segoe UI", Tahoma, sans-serif;
  --ax-font-mono: var(--font-jbmono, "JetBrains Mono"), ui-monospace, "SF Mono", "Cascadia Mono", Menlo, monospace;

  /* Semantic scale — shared, never screen-specific (pack rule).
     v2 bump (sponsor 2026-07-12): body minimum raised 14px → 16px desktop,
     17px field-critical iPad; every step re-derived upward. */
  --ax-text-display: 600 34px/42px var(--ax-font-sans);
  --ax-text-title:   600 26px/34px var(--ax-font-sans);
  --ax-text-heading: 600 20px/28px var(--ax-font-sans);
  --ax-text-subheading: 600 17px/24px var(--ax-font-sans);
  --ax-text-body:    400 16px/24px var(--ax-font-sans);
  --ax-text-body-strong: 600 16px/24px var(--ax-font-sans);
  --ax-text-field:   400 17px/26px var(--ax-font-sans);   /* iPad field-critical minimum */
  --ax-text-caption: 400 14px/20px var(--ax-font-sans);
  --ax-text-micro:   600 12px/16px var(--ax-font-mono);   /* labels/overlines only, uppercase mono */
  /* KPIs, dates, coordinates, timers, SLA — tabular numerals mandatory */
  --ax-numeric-features: "tnum" 1, "lnum" 1;

  /* ---- Spacing · 4px base; rhythm 8/12/16/24/32/48 (pack §Geometry) ---- */
  --ax-space-050: 4px;
  --ax-space-100: 8px;
  --ax-space-150: 12px;
  --ax-space-200: 16px;
  --ax-space-250: 20px;
  --ax-space-300: 24px;
  --ax-space-400: 32px;
  --ax-space-600: 48px;

  /* ---- Radius (pack: 8 small / 12 card-input / 16 panel-modal) ---- */
  --ax-radius-small: 8px;
  --ax-radius-standard: 12px;
  --ax-radius-large: 16px;
  --ax-radius-full: 999px;

  /* ---- Elevation — dark theme: shadows are black-based, never text-based ---- */
  --ax-shadow-raised: 0 1px 2px color-mix(in srgb, var(--ax-color-shadow-base) 30%, transparent),
                      0 2px 6px color-mix(in srgb, var(--ax-color-shadow-base) 25%, transparent);
  --ax-shadow-overlay: 0 12px 32px color-mix(in srgb, var(--ax-color-shadow-base) 55%, transparent);

  /* ---- Control metrics (pack: desktop 40–44px; field/iPad ≥48px) ----
     v2: +4px across the board to carry the larger type. */
  --ax-control-height: 44px;
  --ax-control-height-prominent: 48px;
  --ax-control-height-field: 52px;     /* iPad / touch minimum target */
  --ax-focus-ring: 0 0 0 2px var(--ax-color-canvas), 0 0 0 4px var(--ax-color-primary);

  /* ---- Motion — direct, responsive, optimistic; no decoration ---- */
  --ax-motion-fast: 120ms cubic-bezier(.2,0,0,1);
  --ax-motion-standard: 200ms cubic-bezier(.2,0,0,1);

  /* ---- Layout grids ---- */
  --ax-grid-desktop-max: 1440px;   /* 12-col, 24px gutter */
  --ax-grid-gutter: var(--ax-space-300);
  --ax-shell-nav-width: 248px;
  --ax-shell-panel-width: 360px;   /* side context/audit/properties panel */

  /* ---- Z-index ladder ---- */
  --ax-z-sticky: 10;
  --ax-z-drawer: 40;
  --ax-z-modal: 50;
  --ax-z-toast: 60;
  --ax-z-tooltip: 70;

  color-scheme: dark;
}

