// Blocking theme resolver — runs in <head> before first paint so there is no
// light-then-dark flash. Reads the persisted choice; if none, leaves the
// attribute off so tokens.css falls through to the OS prefers-color-scheme.
// Kept as a raw string (not a bundled module) so it executes synchronously.
const THEME_INIT = `(function(){try{var t=localStorage.getItem('saqeel-theme');if(t==='light'||t==='dark'){document.documentElement.setAttribute('data-theme',t);}}catch(e){}})();`;

export default function ThemeScript() {
  return <script dangerouslySetInnerHTML={{ __html: THEME_INIT }} />;
}

"use client";
import { useEffect, useState } from "react";

// Light/dark switch. The effective theme is whatever tokens.css resolved
// (explicit choice > OS preference > dark); this control reads the live
// resolution on mount, then writes an explicit choice that persists and is
// re-applied before paint by ThemeScript.
type Mode = "light" | "dark";

function resolved(): Mode {
  if (typeof document === "undefined") return "dark";
  const attr = document.documentElement.getAttribute("data-theme");
  if (attr === "light" || attr === "dark") return attr;
  return window.matchMedia?.("(prefers-color-scheme: light)").matches ? "light" : "dark";
}

export default function ThemeToggle({ className, labels }: {
  className?: string;
  labels?: { toLight: string; toDark: string };
}) {
  const [mode, setMode] = useState<Mode>("dark");
  useEffect(() => { setMode(resolved()); }, []);

  const l = labels ?? { toLight: "Light mode", toDark: "Dark mode" };
  const next: Mode = mode === "dark" ? "light" : "dark";
  const label = next === "light" ? l.toLight : l.toDark;

  function toggle() {
    document.documentElement.setAttribute("data-theme", next);
    try { localStorage.setItem("saqeel-theme", next); } catch { /* private mode */ }
    setMode(next);
  }

  return (
    <button type="button" className={className} onClick={toggle} aria-label={label} title={label}>
      {mode === "dark" ? (
        // currently dark → offer sun
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true">
          <circle cx="12" cy="12" r="4" /><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4" />
        </svg>
      ) : (
        // currently light → offer moon
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z" />
        </svg>
      )}
    </button>
  );
}

