tool_input.content:
/* ============================================================================
   SAQEEL — UNIFIED SIGN-IN (SCR-PUB-010 v3)
   Quiet split: a brand panel (logomark + wordmark + tagline + ministry line
   over a decorative, non-live national motif) beside one credential form.
   The form is the dominant element; the brand panel is calm texture. Works
   in both themes (tokens only — no raw values outside tokens.css).
   Shared with /reset: .lg-page (base), .lg-topbar, .lg-center, .lg-card,
   .lg-credentials, .lg-pwwrap, .lg-pwtoggle, .lg-submit, .lg-waiting.
   ========================================================================== */

.lg-page { min-block-size: 100dvh; display: flex; flex-direction: column;
  background: var(--ax-color-canvas);
  color: var(--ax-color-text); font: var(--ax-text-body); }

/* Split variant (login): brand panel + form panel. Form panel is the wider,
   dominant column so the eye lands on the task, not the decoration. */
.lg-page--split { display: grid; grid-template-columns: minmax(0, 0.9fr) minmax(440px, 1fr); }
@media (max-width: 960px) { .lg-page--split { grid-template-columns: 1fr; } }

/* ---- brand panel ---------------------------------------------------- */
.lg-brand { position: relative; overflow: hidden; display: flex;
  padding: clamp(28px, 4vw, 64px);
  background:
    radial-gradient(130% 100% at 12% 0%,
      color-mix(in srgb, var(--ax-color-primary) 14%, transparent), transparent 62%),
    var(--ax-color-canvas);
  border-inline-end: 1px solid var(--ax-color-border); }
@media (max-width: 960px) { .lg-brand { display: none; } }

.lg-brand__inner { position: relative; z-index: 1; margin-block-start: auto;
  display: flex; flex-direction: column; gap: var(--ax-space-300); }

.lg-brand__lockup { display: flex; align-items: center; gap: var(--ax-space-200); }
.lg-brand__mark { inline-size: 52px; block-size: 52px; color: var(--ax-color-primary);
  flex-shrink: 0; }
.lg-brand__names { display: flex; flex-direction: column; gap: 2px; min-inline-size: 0; }
.lg-brand__wordmark { font: 700 34px/1.15 var(--ax-font-arabic); color: var(--ax-color-text); }
.lg-brand__latin { font: var(--ax-text-caption); letter-spacing: 0.02em;
  color: var(--ax-color-text-secondary); }

.lg-brand__tagline { display: flex; flex-direction: column; gap: 2px;
  font: 500 26px/34px var(--ax-font-sans); color: var(--ax-color-text-secondary); }
.lg-brand__tagline span:first-child { color: var(--ax-color-text); }

.lg-brand__ministry { font: var(--ax-text-caption); color: var(--ax-color-text-secondary);
  padding-block-start: var(--ax-space-200); border-block-start: 1px solid var(--ax-color-border); }

/* decorative national motif — low-opacity texture, never a data view */
.lg-motif { position: absolute; inset-block-start: -6%; inset-inline-end: -12%;
  inline-size: 78%; block-size: auto; opacity: 0.5; pointer-events: none; z-index: 0; }
.lg-motif__fill { fill: color-mix(in srgb, var(--ax-color-primary) 6%, transparent); stroke: none; }
.lg-motif__grat { fill: color-mix(in srgb, var(--ax-color-primary) 45%, transparent); }
.lg-motif__grid { opacity: 0.4; }
.lg-motif__outline { fill: none; stroke: color-mix(in srgb, var(--ax-color-primary) 55%, transparent);
  stroke-width: 1.25; stroke-linejoin: round; }

/* ---- form panel ------------------------------------------------------ */
.lg-panel { display: flex; flex-direction: column; min-inline-size: 0;
  background: var(--ax-color-canvas); }

.lg-topbar { display: flex; align-items: center; justify-content: space-between;
  padding: var(--ax-space-250) clamp(20px, 4vw, 48px); }
.lg-topbar__brand { font: 700 20px/28px var(--ax-font-arabic); color: var(--ax-color-text); }

.lg-controls { display: inline-flex; align-items: center; gap: var(--ax-space-100); }
.lg-iconbtn { display: grid; place-items: center; inline-size: 40px; block-size: 40px;
  border: 1px solid var(--ax-color-border); border-radius: var(--ax-radius-full);
  background: var(--ax-color-surface); color: var(--ax-color-text-secondary); cursor: pointer;
  transition: color var(--ax-motion-fast), border-color var(--ax-motion-fast); }
.lg-iconbtn:hover { color: var(--ax-color-text); border-color: var(--ax-color-border-strong); }
.lg-iconbtn:focus-visible { outline: none; box-shadow: var(--ax-focus-ring); }
.lg-lang { display: inline-flex; align-items: center; block-size: 40px; padding-inline: var(--ax-space-150);
  font: var(--ax-text-body-strong); color: var(--ax-color-primary-hover); text-decoration: none;
  border-radius: var(--ax-radius-full); }
.lg-lang:hover { text-decoration: underline; text-underline-offset: 3px; }

.lg-center { flex: 1; display: grid; place-items: center;
  padding: var(--ax-space-300) clamp(20px, 4vw, 48px); }

.lg-card { inline-size: min(100%, 400px); display: flex; flex-direction: column;
  gap: var(--ax-space-250); }
.lg-card__title { margin: 0; font: var(--ax-text-title); color: var(--ax-color-text); }
.lg-card__sub { margin: 0; margin-block-start: calc(-1 * var(--ax-space-150));
  font: var(--ax-text-body); color: var(--ax-color-text-secondary); }

/* ---- credential form -------------------------------------------------- */
.lg-credentials { display: flex; flex-direction: column; gap: var(--ax-space-200); }
.lg-pwwrap { position: relative; }
.lg-pwwrap .ax-input { padding-inline-end: 48px; }
.lg-pwtoggle { position: absolute; inset-block-start: 50%; inset-inline-end: var(--ax-space-100);
  transform: translateY(-50%); display: grid; place-items: center;
  inline-size: 36px; block-size: 36px; border: none; border-radius: var(--ax-radius-small);
  background: none; color: var(--ax-color-text-secondary); cursor: pointer; }
.lg-pwtoggle:hover { color: var(--ax-color-text); background: var(--ax-color-neutral-tint); }
.lg-submit { inline-size: 100%; margin-block-start: var(--ax-space-050); }
.lg-linkbtn { align-self: center; background: none; border: none; padding: 0; cursor: pointer;
  font: var(--ax-text-body-strong); color: var(--ax-color-primary-hover); }
.lg-linkbtn:hover { text-decoration: underline; text-underline-offset: 3px; }

/* ---- reset-page waiting state (shared) -------------------------------- */
.lg-waiting { display: flex; flex-direction: column; align-items: center;
  gap: var(--ax-space-200); text-align: center; }
.lg-waiting__spinner { inline-size: 36px; block-size: 36px; border-radius: var(--ax-radius-full);
  border: 3px solid var(--ax-color-border);
  border-block-start-color: var(--ax-color-primary);
  animation: lg-spin 0.9s linear infinite; }
@keyframes lg-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .lg-waiting__spinner { animation-duration: 2.4s; } }

/* ---- footer ------------------------------------------------------------ */
.lg-foot { display: flex; flex-wrap: wrap; align-items: center; gap: var(--ax-space-200);
  padding: var(--ax-space-250) clamp(20px, 4vw, 48px);
  border-block-start: 1px solid var(--ax-color-border);
  font: var(--ax-text-caption); color: var(--ax-color-text-secondary); }
.lg-foot__item { display: inline-flex; align-items: center; gap: var(--ax-space-100); }
.lg-foot__item svg { color: var(--ax-color-success); }
.lg-foot__copy { margin-inline-start: auto; }

