import { execSync } from "node:child_process";

const REF = "iiozvqntawxfwbgffzqu";
const SB_URL = `https://${REF}.supabase.co`;
const PAT = execSync(`security find-generic-password -w -s "supabase-pat"`).toString().trim();

// 1) reveal service_role key via Management API
const keysRes = await fetch(`https://api.supabase.com/v1/projects/${REF}/api-keys?reveal=true`, {
  headers: { Authorization: `Bearer ${PAT}` },
});
if (!keysRes.ok) { console.error("keys fetch failed", keysRes.status, await keysRes.text()); process.exit(1); }
const keys = await keysRes.json();
const service = keys.find(k => k.name === "service_role" || k.type === "secret")?.api_key
  ?? keys.find(k => /service/i.test(k.name))?.api_key;
if (!service) { console.error("no service_role key in", keys.map(k => k.name)); process.exit(1); }

const admin = (path, init = {}) => fetch(`${SB_URL}/auth/v1/admin${path}`, {
  ...init,
  headers: { apikey: service, Authorization: `Bearer ${service}`, "Content-Type": "application/json", ...(init.headers || {}) },
});

// 2) list users (page through)
let users = [], page = 1;
for (;;) {
  const r = await admin(`/users?per_page=200&page=${page}`);
  if (!r.ok) { console.error("list failed", r.status, await r.text()); process.exit(1); }
  const j = await r.json();
  users.push(...(j.users || []));
  if (!j.users || j.users.length < 200) break;
  page++;
}

// 3) rename @mim.example -> @mim.gov.sa
const targets = users.filter(u => u.email && u.email.endsWith("@mim.example"));
console.log(`users total ${users.length}; renaming ${targets.length}`);
for (const u of targets) {
  const next = u.email.replace(/@mim\.example$/, "@mim.gov.sa");
  const r = await admin(`/users/${u.id}`, {
    method: "PUT",
    body: JSON.stringify({ email: next, email_confirm: true }),
  });
  console.log(`${u.email} -> ${next}: ${r.ok ? "ok" : "FAIL " + r.status + " " + (await r.text())}`);
}
console.log("done");

