          fill="var(--ax-color-surface)" stroke="var(--ax-color-border)" />
        <circle cx="-48" cy="0" r="3.5" fill="var(--ax-color-primary)" />
        <text x="-38" y="4" fill="var(--ax-color-text)"
          style={{ font: "600 12px var(--ax-font-mono)" }}>RIYADH · GEOFENCED</text>
      </g>
    </svg>
  );
}

